//! Cargo lock/checksum serialization and validated manifest types.
//! Kiểu serialize Cargo lock/checksum và manifest đã kiểm tra.

use serde::Serialize;
use std::collections::BTreeMap;

pub(in crate::install) const CARGO_LOCK_HEADER: &str =
    "# This file is automatically @generated by Cargo.\n# It is not intended for manual editing.\n";
pub(in crate::install) const CARGO_LOCK_VERSION: i64 = 4;
pub(in crate::install) const CRATES_IO_SOURCE: &str =
    "registry+https://github.com/rust-lang/crates.io-index";

#[derive(Serialize)]
pub(in crate::install) struct CargoLock {
    pub(in crate::install::cargo_compat) version: i64,
    pub(in crate::install::cargo_compat) package: Vec<CargoPackage>,
}

#[derive(Serialize)]
pub(in crate::install) struct CargoPackage {
    pub(in crate::install::cargo_compat) name: String,
    pub(in crate::install::cargo_compat) version: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub(in crate::install::cargo_compat) source: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub(in crate::install::cargo_compat) checksum: Option<String>,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub(in crate::install::cargo_compat) dependencies: Vec<String>,
}

#[derive(Serialize)]
pub(in crate::install) struct CargoChecksum<'a> {
    pub(in crate::install::cargo_compat) files: BTreeMap<String, String>,
    pub(in crate::install::cargo_compat) package: &'a str,
}

/// Parsed and prevalidated subset of a single-package Cargo manifest.
/// Tập con Cargo manifest đơn-package đã được parse và kiểm tra policy.
#[derive(Debug, Clone)]
pub(in crate::install) struct CargoProjectManifest {
    pub(in crate::install::cargo_compat) document: toml::Value,
    pub(in crate::install::cargo_compat) root_name: String,
    pub(in crate::install::cargo_compat) root_version: String,
}
